python3 << 'PYEOF'
import os
import re
from collections import defaultdict

REPO = "/bench/repo"

# Data layer: store package tree + generated store protos
DATA_LAYER_PREFIXES = (
    "store/",
    "proto/gen/store/",
    "proto/store/",  # .proto sources
)

def is_data_layer(rel_path):
    return any(rel_path.startswith(p) for p in DATA_LAYER_PREFIXES)

def go_package_dir(rel_path):
    """Return Go package directory (relative to repo root)."""
    d = os.path.dirname(rel_path)
    return d if d else "."

# Persistent entity types: struct types with Driver CRUD in store/driver.go
ENTITIES = [
    "Attachment",
    "Memo",
    "MemoRelation",
    "InstanceSetting",
    "User",
    "UserSetting",
    "IdentityProvider",
    "Inbox",
    "Reaction",
    "MemoShare",
    "UserIdentity",
]

# Patterns for store.* entity references
def entity_patterns(name):
    return [
        re.compile(r'\bstore\.' + name + r'\b'),
        re.compile(r'\[\]\*store\.' + name + r'\b'),
        re.compile(r'\*store\.' + name + r'\b'),
    ]

# storepb patterns for proto-backed entities
PROTO_ENTITIES = {
    "InstanceSetting": [r'\bstorepb\.InstanceSetting\b', r'\bstorepb\.InstanceSettingKey\b'],
    "UserSetting": [r'\bstorepb\.UserSetting\b', r'\bstorepb\.UserSettingKey\b'],
    "IdentityProvider": [r'\bstorepb\.IdentityProvider\b'],
    "Memo": [r'\bstorepb\.MemoPayload\b'],  # payload is part of Memo entity
    "Attachment": [r'\bstorepb\.Attachment\b'],
    "Inbox": [r'\bstorepb\.Inbox\b'],
}

entity_pkg_refs = {e: set() for e in ENTITIES}
entity_file_refs = {e: set() for e in ENTITIES}

# Collect all Go files
go_files = []
for root, dirs, files in os.walk(REPO):
    if '/.git/' in root:
        continue
    for f in files:
        if f.endswith('.go'):
            full = os.path.join(root, f)
            rel = os.path.relpath(full, REPO)
            go_files.append((rel, open(full, encoding='utf-8', errors='replace').read()))

for rel, content in go_files:
    if is_data_layer(rel):
        continue
    pkg = go_package_dir(rel)
    for entity in ENTITIES:
        matched = False
        for pat in entity_patterns(entity):
            if pat.search(content):
                matched = True
                break
        # Also check storepb for relevant entities
        if entity in PROTO_ENTITIES:
            for pp in PROTO_ENTITIES[entity]:
                if re.search(pp, content):
                    matched = True
                    break
        if matched:
            entity_pkg_refs[entity].add(pkg)
            entity_file_refs[entity].add(rel)

print("=== Entity type -> distinct external Go package count ===")
ranked = sorted(ENTITIES, key=lambda e: (-len(entity_pkg_refs[e]), e))
for e in ranked:
    pkgs = sorted(entity_pkg_refs[e])
    print(f"{e:20s} {len(pkgs):3d} packages")
    for p in pkgs:
        print(f"    {p}")

print("\n=== TOP 2 ===")
for e in ranked[:2]:
    print(f"#{ranked.index(e)+1} {e}: ~{len(entity_pkg_refs[e])} distinct packages")
PYEOF

