perl -e '
use strict; use warnings;
my $repo = "/bench/repo";
my @entities = qw(Attachment Memo MemoRelation InstanceSetting User UserSetting IdentityProvider Inbox Reaction MemoShare UserIdentity);
my @dl_prefixes = ("store/", "proto/gen/store/", "proto/store/");

sub is_dl {
  my ($p) = @_;
  for my $pre (@dl_prefixes) { return 1 if index($p, $pre) == 0; }
  return 0;
}

my %pkg_refs; # entity -> {pkg => 1}
for my $e (@entities) { $pkg_refs{$e} = {}; }

opendir(my $dh, $repo) or die $!;
my @dirs = readdir $dh;
closedir $dh;

my @files;
use File::Find;
find(sub {
  return unless /\.go$/;
  my $rel = $File::Find::name;
  $rel =~ s/^\Q$repo\E\/?//;
  return if is_dl($rel);
  push @files, $rel;
}, $repo);

for my $rel (@files) {
  open my $fh, "<", "$repo/$rel" or next;
  local $/; my $c = <$fh>; close $fh;
  my $pkg = $rel; $pkg =~ s/\/[^\/]+$//; $pkg = "." unless length $pkg;
  for my $e (@entities) {
    my $matched = 0;
    $matched = 1 if $c =~ /\bstore\.$e\b/;
    $matched = 1 if $c =~ /\*store\.$e\b/;
    $matched = 1 if $c =~ /\[\]\*store\.$e\b/;
    # proto patterns
    if ($e eq "InstanceSetting") { $matched = 1 if $c =~ /\bstorepb\.InstanceSetting\b/ || $c =~ /\bstorepb\.InstanceSettingKey\b/; }
    if ($e eq "UserSetting") { $matched = 1 if $c =~ /\bstorepb\.UserSetting\b/ || $c =~ /\bstorepb\.UserSettingKey\b/; }
    if ($e eq "IdentityProvider") { $matched = 1 if $c =~ /\bstorepb\.IdentityProvider\b/; }
